public static boolean isAsciiControl(final char ch) {
  // Use a range check first to avoid calling 'predicate' for chars 7 bit
  if (ch < 32 || ch > 127) {
    return true;
  }

  // Use a predicate to check whether the character is ASCII control
  Predicate<Character> predicate = c -> c < 32 || c == 127;
  return predicate.test(ch);
}

