    // List of abstract types based on the current frame
    List<? extends Type> abstractTypes = currentFrame.getAbstractTypes();

    // Get the JVMS verification_type_info format for each abstract type
    List<Integer> jvmTypes = abstractTypes.stream()
      .map(type -> StackMapTableWriter.getJvmType(type))
      .collect(Collectors.toList());

    // Get the number of abstract types
    int numAbstractTypes = jvmTypes.size();

    // Check that start and end are within bounds
    if (start < 0 || start >= numAbstractTypes || end < 0 || end > numAbstractTypes) {
      throw new IndexOutOfBoundsException("start and end must be non-negative and less than NumAbstractTypes");
    }

    // Write the abstract types in the JVMS format to stackMapTableEntries
    for (int i = start; i < end; i++) {
      ByteWriter.writeUByte(jvmTypes.get(i));
    }
  }

