    // Initialize a new array without null elements
    String[] result = new String[length];

    // Loop through the array and copy the non-null elements to the new array
    int count = 0;
    for (int i = 0; i < length; i++) {
        if (array[i] != null) {
            result[count] = (String) array[i];
