  if (node.getLeft() == null) {
    // there's no left child, no rotation required
    return node;
  }
  // create a new parent for the right subtree
  TreeNode<T> newParent = node.getRight().getLeft();
  // rename node's right child to use node as its left child
  node.setRight(newParent);
  // set node as the right child of its original left child
  newParent.setLeft(node);
  return newParent;
}

