private boolean unlink(ListNodeImpl<E> node) {
    ListNodeImpl<E> prev = node.prev;
    ListNodeImpl<E> next = node.next;
    if (prev == null) {
        if (next == null) {
            // node is the only node in the list
            clear();
            return true;
        }
        next.prev = null;
        first = next;
    } else {
        if (next == null) {
            // node is the last node in the list
            prev.next = null;
            last = prev;
        } else {
            // node is somewhere in the middle of the list
            prev.next = next;
            next.prev = prev;
        }
    }
    size--;
    node.prev = node.next = null;
    return true;
}

