public static <V,E>IsomorphicGraphMapping<V,E> identity(Graph<V,E> graph) {
    // Create a newIsomorphicGraphMapping instance
    IsomorphicGraphMapping<V,E> mapping = new IsomorphicGraphMapping<V,E>();

    // For each vertex in the graph
    for (V vertex : graph.vertices()) {
        // Add a mapping from the vertex to itself
        mapping.put(vertex, vertex);
    }

    // For each edge in the graph
    for (E edge : graph.edges()) {
        // Get the source and target vertices of the edge
        V source = graph.source(edge);
        V target = graph.target(edge);

        // Add a mapping from the edge to an identical edge
        mapping.put(edge, graph.edgeBetween(source, target));
    }

    return mapping;
}

