    // Create a circulator to start searching from the given node
    OuterFaceCirculator nodeCirculator = new OuterFaceCirculator(start);

    // If the direction is clockwise, we need to search for the first node that does not satisfy the predicate
    if (dir == Clockwise) {
        // Keep moving the circulator while the current node does not satisfy the predicate
        while (!predicate.test(nodeCirculator.getNode())) {
            nodeCirculator.next();
        }
    }
    // If the direction is counterclockwise, we need to search for the first node that does satisfy the predicate
    else {
        // Keep moving the circulator while the current node does satisfy the predicate
        while (predicate.test(nodeCirculator.getNode())) {
            nodeCirculator.next();
        }
    }

    // If we reached the stop node, then we did not find a node that satisfies the predicate
    if (nodeCirculator.getNode() == stop) {
        return null;
    }

    // We found a node that satisfies the predicate, return it
    return nodeCirculator;
}

