    List<Integer> lowerBounds = new ArrayList<>();

    // Initialize the lower bounds to the minimum value.
    for (int i = 0; i < keys.size(); i++) {
        lowerBounds.add(Integer.MIN_VALUE);
    }

    // Go through every key and update the lower bounds.
    for (int i = 0; i < keys.size(); i++) {
        K key = keys.get(i);
        lowerBounds.set(i, Math.max(lowerBounds.get(i), key.getLowerBound()));
    }

    return lowerBounds;
}

