public boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    /*
     * Check whether the subgraph of <code>graph</code> induced by the given <code>vertices</code> is complete, i.e. a clique.
     */

    // Check if the given vertices is a subset of the graph vertex set
    if (!graph.vertexSet().containsAll(vertices)) {
        return false;
    }

    // Check if the subgraph is complete
    return graph.edgeSet().containsAll(vertices.stream().flatMap(v -> vertices.stream().filter(u -> v.equals(u)).map(u -> Pair.of(v, u))));
}

