    // Check if the subgraph is connected
    if(!Graphs.isConnected(graph, vertices)){
        return false;
    }

    // Check if the subgraph is complete
    for(V v1 : vertices){
        for(V v2 : vertices){
            if(graph.containsEdge(v1, v2) && !vertices.contains(v1)){
                return false;
            }
        }
    }
    return true;
}

