public String unescapeId(String input) {
    Pattern pattern = Pattern.compile("\\\\([0-9])");
    Matcher matcher = pattern.matcher(input);
    StringBuffer sb = new StringBuffer();
    while (matcher.find()) {
        matcher.appendReplacement(sb, (char) (matcher.group(1).charAt(0) - '0' + 32));
    }
    matcher.appendTail(sb);
    return sb.toString();
}

