builder.append('\\');
index++;
char nextNextChar = str.charAt(index);
if (nextNextChar == 'n') {
builder.append('\n');
index++;
} else if (nextNextChar == 't') {
builder.append('\t');
index++;
} else {
builder.append(nextChar);
}
} else {
builder.append(nextChar);
}
index++;
}
return builder.toString();
}

