  // If the path is null or is relative to the root directory, return the relative path
  if (path == null || path.equals("/")) {
    return relativePath;
  }

  // Split the path into its components
  String[] pathComponents = path.split("/");

  // Split the relative path into its components
  String[] relativePathComponents = relativePath.split("/");

  // Create a list to store the combined path components
  List<String> combinedPathComponents = new ArrayList<>();

  // Iterate through the path components and the relative path components
  for (int i = 0; i < pathComponents.length || i < relativePathComponents.length; i++) {
    // If the current component of the path is "..", remove the previous component of the path
    // Otherwise, add the current component of the path to the combined path
    if (pathComponents[i].equals("..")) {
      combinedPathComponents.remove(combinedPathComponents.size() - 1);
    } else {
      combinedPathComponents.add(pathComponents[i]);
    }
  }

  // Join the combined path components into a single string using "/" as the separator
  String combinedPath = "/" + String.join("/", combinedPathComponents);

  // Return the combined path
  return combinedPath;
}

