    if (!distUrl.startsWith("https://")) {
        throw new IllegalStateException("Invalid distribution URL: " + distUrl);
    }

    // Download and extract the distribution
    Path zipPath = Paths.get(distUrl);
    Path extractedDir = Paths.get(esHome, "bin");
    try {
        // Download the distribution
        URL url = new URL(distUrl);
        HttpURLConnection urlConnection = (HttpURLConnection) url.openConnection();
        urlConnection.setRequestMethod("GET");
        urlConnection.connect();
        int status = urlConnection.getResponseCode();
        if (status < 200 || status > 299) {
            throw new IOException("HTTP error code: " + status);
        }

        // Extract the distribution
        try (InputStream inputStream = urlConnection.getInputStream();
             OutputStream outputStream = new FileOutputStream(zipPath.toFile())) {
            byte[] buffer = new byte[1024];
            int len;
            while ((len = inputStream.read(buffer)) > 0) {
                outputStream.write(buffer, 0, len);
            }
        }

        // Extract the distribution to the specified directory
