    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    FileInputStream inputStream = null;
    try {
        inputStream = new FileInputStream(file);
        byte[] buf = new byte[1024];
        while (inputStream.available() > 0) {
            int len = inputStream.read(buf);
            if (len <= 0) {
                continue;
            }
            MyDataInputStream dis = new MyDataInputStream(buf, len);
            int magic = dis.readInt();
            if (magic != 0xCAFEBABE) {
                // Not a valid snapshot file
            }
            String token = dis.readUTF8();
            if (!token.equals("PROFILE_THREAD_SNAPSHOT")) {
                // Not a valid snapshot file
            }
            byte[] snapshotData = dis.readBytes();
            ThreadSnapshot snapshot = ThreadSnapshot.parseFrom(snapshotData);
            if (snapshot != null) {
                threadSnapshots.add(snapshot);
            }
        }
    } catch (IOException e) {
        LOG.error("Error occurs when parsing thread snapshot " + file.getName(), e);
    } finally {
        if (inputStream != null) {
            inputStream.close();
        }
    }
