    if (desiredCapacity >= 1000) {
        // If the desired capacity is >= 1000, check if it's already a prime number
        if (isPrime(desiredCapacity)) {
            return desiredCapacity;
        }
        // If not, find the nearest prime number above or below the desired capacity
        int primeAbove = desiredCapacity;
        int primeBelow = desiredCapacity;
        do {
            primeAbove = primeAbove + 2;
            primeBelow = primeAbove - 2;
        } while (!isPrime(primeAbove) && !isPrime(primeBelow));
        // Calculate the difference between the desired capacity and the closest prime number
        int primeDiffAbove = desiredCapacity - primeAbove;
        int primeDiffBelow = desiredCapacity - primeBelow;
        // If the difference is greater than 11%, use the nearest prime number
        if (Math.abs(primeDiffAbove) > 0.11 * desiredCapacity || Math.abs(primeDiffBelow) > 0.11 * desiredCapacity) {
