    // Initialize a set to store the prime numbers less than or equal to desiredCapacity
    HashSet<Integer> primeSet = new HashSet<>();
    for (int i = 2; i <= desiredCapacity; i++) {
        primeSet.add(i);
    }

    // Loop through the prime numbers less than or equal to desiredCapacity
    // and check if they are a factor of desiredCapacity.
    // If they are, then they cannot be a prime number,
    // so we just skip them and move to the next one.
    for (int i = 2; i <= desiredCapacity; i++) {
        if (primeSet.contains(i)) {
            int j = i;
            while (j <= desiredCapacity / i) {
                primeSet.remove(j);
